/*
 * A032951  Numbers whose base-16 representation Sum_{i=0..m} d(i)*16^i has
 *          d(i)=0 for all odd i.
 * https://oeis.org/A032951
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the n‑th integer whose hexadecimal representation has
 *            zero digits in all odd positions (counted from the leftmost
 *            digit starting at 0). The sequence can be generated by iterating
 *            over all possible hexadecimal strings of increasing length,
 *            keeping the digits at odd indices equal to 0
 * Range:     u8 n <= 30, u16 n <= 53, u32 n <= 53, u64 n <= 53, u128 n <= 53,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* required includes for seq_t and idx_t are supplied by the build */
#include <stddef.h>
#include <stdbool.h>
#include <stdint.h>

static seq_t pow16[32] = {0};
static bool pow16_inited = false;

static inline void init_pow16(void) {
    if (pow16_inited) return;
    pow16[0] = (seq_t)1;
    for (int i = 1; i < 32; ++i) {
        pow16[i] = pow16[i-1] * (seq_t)16;
    }
    pow16_inited = true;
}

/* number of terms that have hexadecimal length L */
static inline idx_t count_len(idx_t L) {
    if (L == 1 || L == 2) {
        return 15;
    }
    if (L & 1) {              /* odd length: L = 2k+1 */
        idx_t k = L >> 1;
        return 15ULL * (idx_t)pow16[k];
    } else {                  /* even length: L = 2k */
        idx_t k = L >> 1;
        return 15ULL * (idx_t)pow16[k-1];
    }
}

/* compute the n-th term of the sequence */
seq_t a(idx_t n) {
    init_pow16();

    idx_t L = 1;
    idx_t remaining = n;

    /* locate the length L of the desired term */
    while (true) {
        idx_t cnt = count_len(L);
        if (remaining <= cnt) {
            break;
        }
        remaining -= cnt;
        ++L;
    }

    /* remaining is 1-based index inside the block of length L */
    idx_t idx_in_block = remaining - 1;          /* 0-based */

    idx_t even_count;
    seq_t first_digit;
    seq_t rem = 0;

    /* split works for both odd and even lengths */
    if (L & 1) {                                 /* odd L = 2k+1 */
        idx_t k = L >> 1;                        /* number of lower even digits */
        even_count = k + 1;                      /* total even digits (incl. most sig) */
        seq_t part = pow16[k];                    /* divisor for the most significant digit */
        first_digit = (idx_in_block / part) + 1;  /* 1..15 */
        rem = idx_in_block % part;
    } else {                                     /* even L = 2k */
        idx_t k = L >> 1;
        even_count = k;
        seq_t part = pow16[k-1];
        first_digit = (idx_in_block / part) + 1;  /* 1..15 */
        rem = idx_in_block % part;
    }

    /* extract the remaining even digits (they may be 0..15) */
    seq_t even_digits[20];   /* sufficiently large for all possible even counts */
    even_digits[0] = first_digit;
    idx_t r = 1;
    idx_t lower_count = even_count - 1;
    for (idx_t i = 0; i < lower_count; ++i, ++r) {
        seq_t div = pow16[lower_count - i - 1];
        even_digits[r] = rem / div;
        rem %= div;
    }

    /* build the value from the digits, inserting zeros at odd positions */
    seq_t val = 0;
    idx_t ev = 0;
    for (idx_t i = 0; i < L; ++i) {
        if ((i & 1) == 0) {             /* even position */
            val = val * (seq_t)16 + even_digits[ev++];
        } else {                        /* odd position, digit must be 0 */
            val = val * (seq_t)16;
        }
    }

    return val;
}
